function Get-FrontmatterField {
    param([string]$Content, [string]$Field)
    if ($Content -match '(?ms)^---\s*\r?\n(.*?)\r?\n---') {
        $yaml = $Matches[1]
        if ($yaml -match "(?m)^${Field}:\s*['""](.+?)['""]\s*$") { return $Matches[1].Trim() }
        if ($yaml -match "(?m)^${Field}:\s*(.+)$") { return $Matches[1].Trim().Trim('"').Trim("'") }
    }
    return $null
}

function Convert-SlugToLabelZh {
    param([string]$Slug)
    $parts = $Slug -split '-'
    $words = @()
    foreach ($part in $parts) {
        if ([string]::IsNullOrWhiteSpace($part)) { continue }
        $key = $part.ToLowerInvariant()
        if ($PartZh.ContainsKey($key)) {
            $w = $PartZh[$key]
            if ($w) { $words += $w }
        }
        else {
            $words += ($part.Substring(0, 1).ToUpper() + $part.Substring(1))
        }
    }
    if ($words.Count -eq 0) { return $Slug }
    return ($words -join ' ')
}

function Get-EnglishDescription {
    param([string]$Description)
    if ([string]::IsNullOrWhiteSpace($Description)) { return '' }
    if ($Description -match '\bEN:\s*(.+)$') { return $Matches[1].Trim() }
    return $Description.Trim()
}

function Get-SummaryFromDescription {
    param([string]$Description)
    $en = Get-EnglishDescription -Description $Description
    if ([string]::IsNullOrWhiteSpace($en)) { return '技能说明见正文。' }
    $first = ($en -split '\.\s+')[0]
    if ($first.Length -gt 140) { $first = $first.Substring(0, 137) + '...' }
    return ($first + '（自动摘要，待完善）')
}

function Test-HasCjk {
    param([string]$Text)
    return ($Text -match '[\u4e00-\u9fff]')
}

function Get-AllSkillSlugs {
    $slugs = [ordered]@{}
    foreach ($rel in @('.cursor\skills', '.claude\skills', '.codex\skills')) {
        $root = Join-Path $env:USERPROFILE $rel
        if (-not (Test-Path -LiteralPath $root)) { continue }
        Get-ChildItem -LiteralPath $root -Directory -ErrorAction SilentlyContinue | ForEach-Object {
            $skillFile = Join-Path $_.FullName 'SKILL.md'
            if (Test-Path -LiteralPath $skillFile) {
                if (-not $slugs.Contains($_.Name)) {
                    $content = Get-Content -LiteralPath $skillFile -Raw -Encoding UTF8
                    $slugs[$_.Name] = @{
                        Path        = (Resolve-Path -LiteralPath $skillFile).Path
                        Description = Get-FrontmatterField -Content $content -Field 'description'
                    }
                }
            }
        }
    }
    return $slugs
}

$descOverrides = @{}
$keywordBoosts = @{}
if (Test-Path -LiteralPath $SyncConfigPath) {
    $cfg = Get-Content -LiteralPath $SyncConfigPath -Raw -Encoding UTF8 | ConvertFrom-Json
    if ($cfg.descriptionOverrides) {
        $cfg.descriptionOverrides.PSObject.Properties | ForEach-Object { $descOverrides[$_.Name] = [string]$_.Value }
    }
    if ($cfg.promptKeywordBoosts) {
        $cfg.promptKeywordBoosts.PSObject.Properties | ForEach-Object { $keywordBoosts[$_.Name] = @($_.Value) }
    }
}

$existing = @{}
if (Test-Path -LiteralPath $LocalePath) {
    $raw = Get-Content -LiteralPath $LocalePath -Raw -Encoding UTF8 | ConvertFrom-Json
    $raw.skills.PSObject.Properties | ForEach-Object { $existing[$_.Name] = $_.Value }
}

$allSlugs = Get-AllSkillSlugs
$added = 0
$kept = 0

foreach ($slug in ($allSlugs.Keys | Sort-Object)) {
    if ($existing.ContainsKey($slug)) {
        $kept++
        continue
    }
    $meta = $allSlugs[$slug]
    $label = Convert-SlugToLabelZh -Slug $slug
    $summary = Get-SummaryFromDescription -Description $meta.Description
    if ($descOverrides.ContainsKey($slug) -and (Test-HasCjk -Text $descOverrides[$slug])) {
        $summary = $descOverrides[$slug]
        if ($summary.Length -gt 180) { $summary = $summary.Substring(0, 177) + '...' }
    }
    $triggers = @($slug)
    if ($keywordBoosts.ContainsKey($slug)) {
        $triggers = @($keywordBoosts[$slug] | Select-Object -First 8)
    }
    $existing[$slug] = [pscustomobject]@{
        label_zh     = $label
        summary_zh   = $summary
        triggers_zh  = @($triggers)
        category_zh  = '库'
        auto_generated = $true
    }
    $added++
}

$skillsObj = [ordered]@{}
foreach ($key in ($existing.Keys | Sort-Object)) {
    $skillsObj[$key] = $existing[$key]
}

$out = [ordered]@{
    version = 1
    note    = 'SSOT for tri-end skill Chinese metadata. Regenerate descriptions via apply-skills-locale.ps1'
    skills  = $skillsObj
}

$json = ($out | ConvertTo-Json -Depth 6)
if ($DryRun) {
    Write-Host "[dry-run] would write $($skillsObj.Count) entries (added $added, kept manual $kept)"
}
else {
    Write-Utf8NoBomFile -Path $LocalePath -Content $json
    Write-Host "Locale stubs done. Total=$($skillsObj.Count) Added=$added Kept=$kept"
}

# Apply skills-locale-zh.json to SKILL.md frontmatter across cursor/claude/codex.
# Sets Chinese display name + slug for routing + bilingual description.
param(
    [switch]$DryRun,
    [string]$LocalePath = ''
)

$ErrorActionPreference = 'Stop'
. (Join-Path $PSScriptRoot 'ensure-utf8-console.ps1')
. (Join-Path $PSScriptRoot 'Write-Utf8NoBom.ps1')

if (-not $LocalePath) {
    $LocalePath = Join-Path $env:USERPROFILE '.ai-workspace\skills-locale-zh.json'
}

function Get-FrontmatterYaml {
    param([string]$Content)
    if ($Content -match '(?ms)^---\s*\r?\n(.*?)\r?\n---') { return $Matches[1] }
    return $null
}

function Get-FrontmatterField {
    param([string]$Content, [string]$Field)
    $yaml = Get-FrontmatterYaml -Content $Content
    if (-not $yaml) { return $null }
    if ($yaml -match "(?m)^${Field}:\s*['""](.+?)['""]\s*$") { return $Matches[1].Trim() }
    if ($yaml -match "(?m)^${Field}:\s*(.+)$") { return $Matches[1].Trim().Trim('"').Trim("'") }
    return $null
}

function Get-SkillBody {
    param([string]$Content)
    if ($Content -match '(?ms)^---\s*\r?\n.*?\r?\n---\s*\r?\n(.*)$') { return $Matches[1] }
    return $Content
}

function Get-EnglishDescription {
    param([string]$Description)
    if ([string]::IsNullOrWhiteSpace($Description)) { return '' }
    if ($Description -match '\bEN:\s*(.+)$') { return $Matches[1].Trim() }
    return $Description.Trim()
}

function Build-LocalizedDescription {
    param(
        [string]$English,
        [object]$LocaleEntry
    )
    $label = [string]$LocaleEntry.label_zh
    $summary = [string]$LocaleEntry.summary_zh
    $triggers = @($LocaleEntry.triggers_zh) -join ', '
    $en = Get-EnglishDescription -Description $English
    if ([string]::IsNullOrWhiteSpace($en)) { $en = $summary }
    return ('[' + $label + '] ' + $summary + ' Triggers: ' + $triggers + '. EN: ' + $en)
}

function Escape-YamlDoubleQuoted {
    param([string]$Value)
    return ($Value -replace '\\', '\\\\' -replace '"', '\"')
}

function Set-SkillFrontmatter {
    param(
        [string]$Content,
        [string]$DisplayName,
        [string]$Slug,
        [string]$Description
    )
    $body = Get-SkillBody -Content $Content
    $disable = Get-FrontmatterField -Content $Content -Field 'disable-model-invocation'
    $disableLine = if ($disable -eq 'true') { 'disable-model-invocation: true' } else { 'disable-model-invocation: false' }
    $nameLine = 'name: "' + (Escape-YamlDoubleQuoted -Value $DisplayName) + '"'
    $descLine = 'description: "' + (Escape-YamlDoubleQuoted -Value $Description) + '"'
    $fm = @(
        '---',
        $nameLine,
        ('slug: ' + $Slug),
        $descLine,
        $disableLine,
        '---',
        ''
    ) -join "`n"
    return $fm + $body.TrimStart()
}

function Get-AllSkillFiles {
    $seen = @{}
    $items = @()
    foreach ($rel in @('.cursor\skills', '.claude\skills', '.codex\skills')) {
        $root = Join-Path $env:USERPROFILE $rel
        if (-not (Test-Path -LiteralPath $root)) { continue }
        Get-ChildItem -LiteralPath $root -Directory -ErrorAction SilentlyContinue | ForEach-Object {
            $skillFile = Join-Path $_.FullName 'SKILL.md'
            if (-not (Test-Path -LiteralPath $skillFile)) { return }
            $resolved = (Resolve-Path -LiteralPath $skillFile).Path
            if ($seen.ContainsKey($resolved)) { return }
            $seen[$resolved] = $true
            $items += [pscustomobject]@{
                Path = $resolved
                Slug = $_.Name
            }
        }
    }
    return $items
}

if (-not (Test-Path -LiteralPath $LocalePath)) {
    throw "Missing locale file: $LocalePath"
}
$localeRaw = Get-Content -LiteralPath $LocalePath -Raw -Encoding UTF8 | ConvertFrom-Json
$localeMap = @{}
$localeRaw.skills.PSObject.Properties | ForEach-Object { $localeMap[$_.Name] = $_.Value }

$stats = @{ Patched = 0; MissingLocale = 0; SkippedNoFile = 0 }
$skillFiles = Get-AllSkillFiles

foreach ($item in ($skillFiles | Sort-Object Slug)) {
    if (-not $localeMap.ContainsKey($item.Slug)) {
        $stats.MissingLocale++
        continue
    }
    $content = Get-Content -LiteralPath $item.Path -Raw -Encoding UTF8
    $currentDesc = Get-FrontmatterField -Content $content -Field 'description'
    $localeEntry = $localeMap[$item.Slug]
    $displayName = [string]$localeEntry.label_zh
    if ([string]::IsNullOrWhiteSpace($displayName)) { $displayName = $item.Slug }
    $newDesc = Build-LocalizedDescription -English $currentDesc -LocaleEntry $localeEntry
    if ($newDesc.Length -gt 1024) {
        $newDesc = $newDesc.Substring(0, 1021) + '...'
    }
    $newContent = Set-SkillFrontmatter -Content $content -DisplayName $displayName -Slug $item.Slug -Description $newDesc
    if ($DryRun) {
        Write-Host "[dry-run] patch $($item.Slug) -> $displayName ($($item.Path))"
    }
    else {
        Write-Utf8NoBomFile -Path $item.Path -Content $newContent
    }
    $stats.Patched++
}

Write-Host "Locale apply done. Patched=$($stats.Patched) MissingLocale=$($stats.MissingLocale) Files=$($skillFiles.Count)"

