function readFrontmatterField(content, field) {
  const m = content.match(/^---\s*\r?\n([\s\S]*?)\r?\n---/);
  if (!m) return '';
  const yaml = m[1];
  const re = new RegExp(`^${field}:\\s*(?:['"](.+?)['"]|(.+))\\s*$`, 'm');
  const fm = yaml.match(re);
  if (!fm) return '';
  return (fm[1] || fm[2] || '').trim().replace(/^["']|["']$/g, '');
}

function slugToLabel(slug) {
  const words = slug.split('-').map((part) => {
    const key = part.toLowerCase();
    if (Object.prototype.hasOwnProperty.call(PART_ZH, key)) {
      return PART_ZH[key];
    }
    return part.charAt(0).toUpperCase() + part.slice(1);
  }).filter(Boolean);
  return words.length ? words.join(' ') : slug;
}

function englishDescription(desc) {
  if (!desc) return '';
  const m = desc.match(/\bEN:\s*(.+)$/);
  return (m ? m[1] : desc).trim();
}

function summaryFromDescription(desc) {
  const en = englishDescription(desc);
  if (!en) return '技能说明见正文。';
  const first = en.split(/\.\s+/)[0];
  return (first.length > 140 ? first.slice(0, 137) + '...' : first) + '（自动摘要，待完善）';
}

function hasCjk(text) {
  return /[\u4e00-\u9fff]/.test(text);
}

function collectSlugs() {
  const slugs = new Map();
  for (const root of skillRoots) {
    if (!fs.existsSync(root)) continue;
    for (const ent of fs.readdirSync(root, { withFileTypes: true })) {
      if (!ent.isDirectory()) continue;
      const skillFile = path.join(root, ent.name, 'SKILL.md');
      if (!fs.existsSync(skillFile)) continue;
      if (!slugs.has(ent.name)) {
        const content = fs.readFileSync(skillFile, 'utf8');
        slugs.set(ent.name, readFrontmatterField(content, 'description'));
      }
    }
  }
  return slugs;
}

const dryRun = process.argv.includes('--dry-run');
const descOverrides = {};
const keywordBoosts = {};
if (fs.existsSync(syncConfigPath)) {
  const cfg = JSON.parse(fs.readFileSync(syncConfigPath, 'utf8'));
  Object.assign(descOverrides, cfg.descriptionOverrides || {});
  Object.assign(keywordBoosts, cfg.promptKeywordBoosts || {});
}

const existing = {};
if (fs.existsSync(localePath)) {
  const raw = JSON.parse(fs.readFileSync(localePath, 'utf8'));
  Object.assign(existing, raw.skills || {});
}

const allSlugs = collectSlugs();
let added = 0;
let kept = 0;

for (const slug of [...allSlugs.keys()].sort()) {
  if (existing[slug]) {
    kept++;
    continue;
  }
  const desc = allSlugs.get(slug);
  let summary = summaryFromDescription(desc);
  if (descOverrides[slug] && hasCjk(descOverrides[slug])) {
    summary = descOverrides[slug].length > 180
      ? descOverrides[slug].slice(0, 177) + '...'
      : descOverrides[slug];
  }
  const triggers = keywordBoosts[slug]
    ? keywordBoosts[slug].slice(0, 8)
    : [slug];
  existing[slug] = {
    label_zh: slugToLabel(slug),
    summary_zh: summary,
    triggers_zh: triggers,
    category_zh: '库',
    auto_generated: true,
  };
  added++;
}

const sortedSkills = {};
for (const key of Object.keys(existing).sort()) {
  sortedSkills[key] = existing[key];
}

const out = {
  version: 1,
  note: 'SSOT for tri-end skill Chinese metadata. Regenerate descriptions via apply-skills-locale.ps1',
  skills: sortedSkills,
};

if (dryRun) {
  console.log(`[dry-run] would write ${Object.keys(sortedSkills).length} entries (added ${added}, kept ${kept})`);
} else {
  fs.writeFileSync(localePath, JSON.stringify(out, null, 2), 'utf8');
  console.log(`Locale stubs done. Total=${Object.keys(sortedSkills).length} Added=${added} Kept=${kept}`);
}

