  const overviewBlock = (body.match(/## Overview\n([\s\S]*?)(?=\n## |\n# |$)/i) || [])[1] || '';
  const bullets = [...whenBlock.matchAll(/^[-*]\s+(.+)$/gm)].map((m) => m[1].trim()).filter(Boolean);
